function getRequestedCastAvatar(name) {
  return requestedCastAvatars[castKey(name)] || "";
}

function castKey(value) {
  return String(value || "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/gi, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

export { getRequestedCastAvatar, requestedCastAvatars };
